-- Definition sync: local -> prod.
-- Replaces prod item/object/npc/action/skill definitions with the local set.
-- Load on prod:  psql "postgresql://postgres:admin@localhost:5432/mmo" -f prod_defs_sync.sql
BEGIN;
SET session_replication_role = replica;  -- skip FK checks during bulk load
TRUNCATE object_definitions, npc_definitions, npc_drops, item_definitions, action_definitions, skill_definitions RESTART IDENTITY CASCADE;
SET session_replication_role = DEFAULT;
COMMIT;
